# ---- Copilot 插件 prompt-optimizer：系统提示词尾部追加「提示词优化纪律」----
# 替换 _base_prompt_parts 的末行（return parts）：只追加尾部，不改开头，
# 保持语言指令在最前的权重与既有前缀缓存友好性。
try:
    from zhuzhu_Copilot.core.prompt_optimizer import PROMPT_DISCIPLINE
    if not any(PROMPT_DISCIPLINE in str(_p) for _p in parts):
        parts.append(PROMPT_DISCIPLINE)
except Exception:
    pass
return parts

# ---- Copilot 插件 prompt-optimizer：提示词优化工具接线 ----
if name == "optimize_prompt":
    try:
        from zhuzhu_Copilot.core import prompt_optimizer
        _po_res = prompt_optimizer.optimize(
            str(args.get("text") or ""), str(args.get("goal") or ""))
        return {"text": prompt_optimizer.format_result(_po_res),
                "images": []}
    except Exception as _po_err:
        return {"text": "提示词优化失败：%s" % _po_err, "images": []}
